package kindergarten

import (
	"errors"
	"sort"
	"strings"
)

type Garden struct {
	rows    []string
	plants  map[string][]string
}

var plantNames = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, errors.New("diagram must start with a newline")
	}
	rows := strings.Split(diagram[1:], "\n")
	if len(rows) != 2 {
		return nil, errors.New("diagram must have two rows")
	}
	if len(rows[0]) != len(rows[1]) {
		return nil, errors.New("rows must be the same length")
	}
	if len(rows[0])%2 != 0 {
		return nil, errors.New("each row must have an even number of cups")
	}
	for _, r := range rows {
		for _, c := range r {
			if _, ok := plantNames[c]; !ok {
				return nil, errors.New("invalid cup code")
			}
		}
	}
	names := make([]string, len(children))
	copy(names, children)
	sort.Strings(names)
	seen := make(map[string]bool, len(names))
	plants := make(map[string][]string, len(names))
	for i, name := range names {
		if seen[name] {
			return nil, errors.New("duplicate name")
		}
		seen[name] = true
		p := make([]string, 4)
		p[0] = plantNames[rune(rows[0][2*i])]
		p[1] = plantNames[rune(rows[0][2*i+1])]
		p[2] = plantNames[rune(rows[1][2*i])]
		p[3] = plantNames[rune(rows[1][2*i+1])]
		plants[name] = p
	}
	return &Garden{plants: plants}, nil
}

func (g *Garden) Plants(child string) ([]string, bool) {
	p, ok := g.plants[child]
	return p, ok
}
```

Caveat: if the number of children exceeds the number of pairs, the index will be out of range. Not tested, but the spec says there are 12 children. We could add a check: len(names)*2 <= len(rows[0]). Adding it for robustness.

Also, the Garden type: the test only uses g.Plants. No problem.

